stop() {
  printf '\n  %s%sSTOP:%s %s\n\n' "$BOLD" "$RED" "$RESET" "$1" >&2
  exit 1
}

confirm_or_stop() {
  confirm "$1" || stop "${2:-The required confirmation was not given.}"
}

require_command() {
  command -v "$1" >/dev/null 2>&1 || stop "Required command '$1' is not installed."
}

require_value() {
  local name="$1" value="$2"
  [[ -n "${value//[[:space:]]/}" ]] || stop "$name cannot be blank."
}

require_sha256() {
  local name="$1" value="$2"
  [[ "$value" =~ ^[a-f0-9]{64}$ ]] || stop "$name must be a lowercase 64-character SHA-256."
}

require_email() {
  local name="$1" value="$2"
  [[ "$value" =~ ^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$ ]] ||
    stop "$name must be a valid email address."
}

validate_neon_connection() {
  local variable_name="$1" mode="$2"
  printf '%s' "${!variable_name}" |
    node scripts/validate-neon-deployment-urls.mjs "$mode"
}

validate_same_neon_database() {
  local pooled_name="$1" direct_name="$2"
  printf '%s\0%s' "${!pooled_name}" "${!direct_name}" |
    node scripts/validate-neon-deployment-urls.mjs pair
}

remove_env() {
  local key="$1" tmp
  [[ -f "$ENV_FILE" ]] || return 0
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  mv "$tmp" "$ENV_FILE"
  printf '  %s✓ removed%s stale %s from %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

write_optional() {
  local key="$1" value="$2"
  if [[ -n "$value" ]]; then
    write_env "$key" "$value"
  else
    remove_env "$key"
  fi
}

generate_secret() {
  local key="$1" current
  current=$(_existing "$key" || true)
  if [[ -z "$current" ]]; then
    current=$(openssl rand -base64 48 | tr -d '\n')
  fi
  printf -v "$key" '%s' "$current"
  write_env "$key" "$current"
}

