    write_env GROK_AUTH_CLIENT_SECRET "$GROK_AUTH_CLIENT_SECRET"
    ;;
  *) stop "AUTH_MODE must be exactly 'email' or 'broker'." ;;
esac
write_env AUTH_MODE "$AUTH_MODE"
write_env VITE_GROK_AUTH_ENABLED "$VITE_GROK_AUTH_ENABLED"

