    docker run --rm -i --platform linux/amd64 \
      --mount "type=volume,source=$NETLIFY_RELEASE_VOLUME,target=/workspace" \
      "$NETLIFY_RELEASE_IMAGE" bash -ceu '
      read_release_value() {
