write_env SMOKE_COUNTRY_NAME "$SMOKE_COUNTRY_NAME"
write_env SMOKE_RUN_ID "$SMOKE_RUN_ID"
write_env SMOKE_ARTIFACT_SET_ID "$SMOKE_ARTIFACT_SET_ID"
write_env SMOKE_BUNDLE_SHA256 "$SMOKE_BUNDLE_SHA256"
write_env SMOKE_WORKFLOW_CONTRACT_SHA256 "$SMOKE_WORKFLOW_CONTRACT_SHA256"
write_env SMOKE_DAMM_MODEL_SHA256 "$SMOKE_DAMM_MODEL_SHA256"
write_env SMOKE_ASSESSMENT_INPUT_SHA256 "$SMOKE_ASSESSMENT_INPUT_SHA256"
write_env SMOKE_BUNDLE_BYTES "$SMOKE_BUNDLE_BYTES"
write_env SMOKE_GATEWAY_ARTIFACT_BYTES "$SMOKE_GATEWAY_ARTIFACT_BYTES"
write_env SMOKE_LIVE_OVER_20_MIB "$SMOKE_LIVE_OVER_20_MIB"
confirm_or_stop "Did every workflow, lifecycle, persistence, format, download, hash, and white-background check pass?" \
  "The completed Draft package did not satisfy staging acceptance."

# ── 17 ────────────────────────────────────────────────────────────────────
stage "Post-completion G1, G2, and G3"
open_url "$NETLIFY_URL"
step "As owner open Human controls. Before assignments require zero human decisions and a locked G3."
step "Temporarily assign pending G1 to $SMOKE_G2_EMAIL. Require its exact-package download access, while the still-unassigned $SMOKE_G1_EMAIL account is denied."
step "Replace that pending G1 assignment with $SMOKE_G1_EMAIL and a reason. Require the superseded account's new artifact request to be denied and the immutable supersession audit to remain visible."
step "Assign G2 to $SMOKE_G2_EMAIL. Require exact-package access again. Attempt to replace G2 with the active G1 account and require rejection."
step "Open G2 before G1: its frozen scope may be visible, but submission must be locked."
step "As G1 decide every machine-filled row, affirm the human role, and record the immutable G1 decision. Reopen it read-only."
step "As the distinct G2 reviewer independently decide every frozen-scope row, affirm, and record G2."
step "As owner confirm G3 unlocks only now, check all seven affirmations, and record the named/dated decision."
step "Require a versioned Approved Draft release; the unratified methodology must never yield Canonical Final. Original Draft downloads must remain unchanged."
ask SMOKE_PACKAGE_ID "Approval package ID:"
require_value SMOKE_PACKAGE_ID "$SMOKE_PACKAGE_ID"
ask SMOKE_TARGET_IDENTITY_SHA256 "Approval target-identity SHA-256:"
require_sha256 SMOKE_TARGET_IDENTITY_SHA256 "$SMOKE_TARGET_IDENTITY_SHA256"
ask SMOKE_G1_DECISION_ID "Immutable G1 decision ID:"
require_value SMOKE_G1_DECISION_ID "$SMOKE_G1_DECISION_ID"
ask SMOKE_G2_DECISION_ID "Immutable G2 decision ID:"
require_value SMOKE_G2_DECISION_ID "$SMOKE_G2_DECISION_ID"
ask SMOKE_G3_DECISION_ID "Immutable G3 decision ID:"
require_value SMOKE_G3_DECISION_ID "$SMOKE_G3_DECISION_ID"
ask SMOKE_RELEASE_ID "Versioned Approved Draft release ID:"
require_value SMOKE_RELEASE_ID "$SMOKE_RELEASE_ID"
write_env SMOKE_PACKAGE_ID "$SMOKE_PACKAGE_ID"
write_env SMOKE_TARGET_IDENTITY_SHA256 "$SMOKE_TARGET_IDENTITY_SHA256"
write_env SMOKE_G1_DECISION_ID "$SMOKE_G1_DECISION_ID"
write_env SMOKE_G2_DECISION_ID "$SMOKE_G2_DECISION_ID"
write_env SMOKE_G3_DECISION_ID "$SMOKE_G3_DECISION_ID"
write_env SMOKE_RELEASE_ID "$SMOKE_RELEASE_ID"
confirm_or_stop "Were G2 independence, early-G3 lock, immutable identities, Draft preservation, and honest release wording all enforced?" \
  "The human-control chain failed live acceptance."

# ── 18 ────────────────────────────────────────────────────────────────────
stage "Neon audit, immutability probe, and closeout"
open_url "https://console.neon.tech/app/projects/$NEON_PROJECT_ID"
step "In SQL Editor run the package/decision/release audit query from the deployment guide using $SMOKE_PACKAGE_ID."
step "Require three human actors, distinct G1/G2 user IDs, owner G3, one exact package/bundle identity, model_ratified=false, lifecycle approved_draft."
step "Run the assignment/supersession query. Require one inactive temporary G1 with one immutable supersession, plus the intended active completed G1 and independent G2."
step "Run the guide's zero-persistence DO-block update probe against G1 decision $SMOKE_G1_DECISION_ID. Require the immutable trigger, then re-query the unchanged identity."
step "Record the Netlify deploy and both separate Render service deploy IDs/commits, Neon project/branch/snapshot, run/package hashes, decision/release IDs, validation results, and UTC completion time."
step "Keep the pre-migration snapshot through acceptance. Rollback order is: block launches, settle runs, suspend both Render services, publish/lock the prior web deploy, then restore Neon only with explicit data-loss authority."
confirm_or_stop "Did the database audit and immutable identity probe pass exactly?" \
  "Do not close staging acceptance with an incomplete audit."
DEPLOYMENT_ACCEPTED_AT_UTC=$(date -u +"%Y-%m-%dT%H:%M:%SZ")
write_env DEPLOYMENT_ACCEPTED_AT_UTC "$DEPLOYMENT_ACCEPTED_AT_UTC"
write_env DEPLOYMENT_READINESS_STATUS "accepted-staging"
chmod 600 "$ENV_FILE"

finish
say "Deployment evidence is in $ENV_FILE (mode 0600, gitignored)."
say "Keep staging Private. This acceptance does not claim DAMM ratification or a canonical Final release."
